// Node: Build SPARQL Query  |  Mode: Run Once for All Items
// Runs right after the Postgres "Load Config" node.
// Input: 1 item -- { wikidata: {entity_class, country, limit, ...}, segment_id }
// Output: 1 item carrying a ready-to-fetch Wikidata query-service URL.
//
// WHY THIS SOURCE IS WORTH A RUNG. Every other connector leaves `domain` null:
// a YouTube description rarely carries a website, and a news headline names a
// company without linking to it. Wikidata has P856 (official website) as a
// first-class property, so this is the one source that arrives WITH the domain
// already attached -- which is exactly what Apollo needs at P16 to match an
// organisation.
//
// A live probe found **363 US film/TV production companies with a website**.
// That is a seed, not a stream: Wikidata is notable-only, so the list changes
// slowly and this workflow is meant to be re-run occasionally, not weekly.
//
// CC0 licensed and free forever -- no key, no quota, no signup. The service
// does require a descriptive User-Agent, which the HTTP node sets.
//
// The entity class and country live in config so Segment 2 is a config row
// rather than a code change: swap Q1762059 (film production company) for
// whatever class that segment hunts.

const row = $input.first().json;
const cfg = row.wikidata || {};
const segmentId = row.segment_id;

// CORRECTED 2026-08-28. The original version queried one class and its
// comment asserted that P31/P279* under "film production company" also
// catches television production companies. A live probe disproved that:
// Q10689397 (television production company) is a SIBLING of Q1762059 in the
// class tree, not a subclass, so the first live run silently missed **124 US
// TV production companies with websites** -- for a TV-format segment, the
// most relevant slice of the source. Classes are now a config ARRAY joined
// with VALUES, and each subclass tree is still walked.
const entityClasses = cfg.entity_classes
  || (cfg.entity_class ? [cfg.entity_class] : ['Q1762059', 'Q10689397']);
const country = cfg.country || 'Q30';        // United States
const limit   = cfg.limit   || 600;

// ONE QUERY PER CLASS, not one query with a VALUES join. The combined
// two-tree query timed out against the query service's 60-second ceiling on
// the first live run (execution #14) -- each P279* subclass walk is expensive
// and the label service multiplies it. A single-class query of exactly this
// shape has already succeeded live, so N classes become N items here; the
// HTTP node runs once per item, and the shaping node merges and dedupes.

// OPTIONALs are genuinely optional: a company missing an inception date should
// still be returned, not filtered out.
return entityClasses.map(cls => {
  const sparql = `
SELECT DISTINCT ?company ?companyLabel ?website ?inception ?dissolved ?parentLabel ?employees WHERE {
  ?company wdt:P31/wdt:P279* wd:${cls} .
  ?company wdt:P17 wd:${country} .
  ?company wdt:P856 ?website .
  OPTIONAL { ?company wdt:P571  ?inception }
  OPTIONAL { ?company wdt:P576  ?dissolved }
  OPTIONAL { ?company wdt:P749  ?parent }
  OPTIONAL { ?company wdt:P1128 ?employees }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT ${limit}`.trim();
  return {
    json: {
      segment_id: segmentId,
      entity_class: cls,
      entity_classes: entityClasses,
      country: country,
      sparql: sparql,
      query_url: 'https://query.wikidata.org/sparql?format=json&query='
                 + encodeURIComponent(sparql)
    }
  };
});

// Node: Shape Wikidata Results  |  Mode: Run Once for All Items
// Runs after the HTTP Request node that calls the Wikidata query service.
// Input: 1 item holding a SPARQL JSON result set.
//
// WHAT THIS CONNECTOR CAN HONESTLY SET, AND WHAT IT CANNOT.
//
//   domain                     -- from P856. THE point of this source. Every
//                                 other connector leaves it null.
//   geography_signal = 'us'    -- the query itself filters on P17 = United
//                                 States, so this is a fact about the result
//                                 set, not a guess.
//   has_reachable_presence     -- it has a published website by construction.
//   activity_signal            -- 'confirmed_dormant' when P576 (dissolution
//                                 date) exists. 38 of the 363 carry one. No
//                                 other connector can supply this gate input,
//                                 and it is the difference between a live shop
//                                 and a company that closed in 2011.
//   major_or_oversized_signal  -- true when the company has a parent
//                                 organisation that is a known major, or its
//                                 own name matches one. Wikidata models
//                                 ownership properly (P749), so subsidiaries
//                                 are detectable here in a way they are not
//                                 from a YouTube channel title.
//
// NOT set: right_size, genre_fit, collaboration_openness,
// international_ip_experience. Wikidata knows a company exists and is notable;
// it does not know whether it makes comedy, wants a partner, or has six people.
// Only 14 of 363 even carry an employee count (P1128), so size is recorded as
// a note when present and left to enrichment otherwise.
//
// THE SIZE PROBLEM, STATED PLAINLY. Wikidata is notable-only, and notable
// skews large: the first page of results is Icon Productions, Relativity
// Media, Warner Independent. The rubric wants 2-20 people. Expect a low hit
// rate and lean on `major_or_oversized_signal` plus the P13 gate to clear the
// obvious misses -- this source earns its place by supplying DOMAINS, not by
// precision.

const KNOWN_MAJORS = [
  'disney', 'warner', 'nbcuniversal', 'universal', 'paramount', 'sony',
  'columbia', 'viacom', 'mgm', 'lionsgate', 'netflix', 'amazon', 'hbo', 'a24',
  '20th century', 'fox', 'dreamworks', 'pixar', 'marvel', 'lucasfilm',
  'miramax', 'legendary', 'blumhouse', 'skydance', 'apple', 'comcast'
];

// Wikidata's P856 is usually right and sometimes WRONG: the live entry for
// Platinum Dunes points at bloody-disgusting.com -- the horror NEWS SITE that
// covers them -- and that bad value re-imported the company with a stranger's
// domain straight after the pool had been cleaned (2026-08-30). Same
// third-party blocklist as the YouTube extractor: platforms and publishers by
// suffix, builders and databases by EXACT host so a small shop's
// <name>.wixsite.com still counts as its own site.
const EXCLUDE_SUFFIX = ['youtube.com', 'youtu.be', 'instagram.com',
  'twitter.com', 'x.com', 'facebook.com', 'tiktok.com', 'linkedin.com',
  'linktr.ee', 'bit.ly', 'vimeo.com', 'patreon.com', 'substack.com',
  'medium.com', 'beacons.ai', 'eventbrite.com', 'mailchimp.com', 'gmail.com'];
const EXCLUDE_EXACT = ['jotform.com', 'wix.com', 'wixsite.com',
  'squarespace.com', 'wordpress.com', 'godaddy.com', 'shopify.com',
  'weebly.com', 'carrd.co', 'imdb.com', 'crunchbase.com', 'variety.com',
  'deadline.com', 'hollywoodreporter.com', 'indiewire.com', 'wikipedia.org',
  'productionlist.com', 'zoominfo.com', 'rocketreach.co',
  'bloody-disgusting.com'];

function hostOf(url) {
  if (!url) return null;
  const m = String(url).match(/^[a-z][a-z0-9+.-]*:\/\/([^/?#]+)/i);
  if (!m) return null;
  const host = m[1].toLowerCase().replace(/^www\./, '') || null;
  if (!host) return null;
  if (EXCLUDE_SUFFIX.some(ex => host === ex || host.endsWith('.' + ex))) return null;
  if (EXCLUDE_EXACT.includes(host)) return null;
  return host;
}

function isMajorName(s) {
  const t = (s || '').toLowerCase();
  return KNOWN_MAJORS.some(k => t.includes(k));
}

// The SPARQL endpoint answers with application/sparql-results+json, but n8n
// does not always hand it back parsed -- on the first live run (2026-08-27) the
// whole document arrived as a STRING, so `resp.results` was undefined, `rows`
// came out empty, and the workflow reported success while inserting nothing.
// Accept every shape rather than assume one: parsed object, string body, or
// wrapped under `data`.
function asResults(v) {
  if (!v) return null;
  if (typeof v === 'string') {
    try { v = JSON.parse(v); } catch (e) { return null; }
  }
  if (v.results && v.results.bindings) return v;
  if (v.data) return asResults(v.data);
  if (v.body) return asResults(v.body);
  return null;
}

// One response PER CLASS arrives here (the fetch node runs once per query
// item), so collect bindings across all of them; the byEntity map below
// already dedupes a company that appears in both class trees.
const rows = [];
for (const item of $input.all()) {
  const body = asResults(item.json);
  if (body) rows.push(...body.results.bindings);
}

// A silent zero here is the failure mode that wasted a live run: the node was
// green, the query was fine, and nothing reached the database. Fail loudly.
if (rows.length === 0) {
  throw new Error(
    'Wikidata returned no usable rows across ' + $input.all().length + ' response(s). First was ' + typeof ($input.first() && $input.first().json) +
    '. If the queries genuinely matched nothing that is a query problem; if the ' +
    'bodies are strings this parser failed to read them.');
}

// Wikidata returns one row per value combination, so a company with two
// inception statements appears twice. Collapse on the entity URI.
const byEntity = new Map();
for (const r of rows) {
  const uri = r.company && r.company.value;
  if (!uri) continue;
  if (!byEntity.has(uri)) byEntity.set(uri, r);
  else {
    // prefer the row that carries the most information
    const cur = byEntity.get(uri);
    if (Object.keys(r).length > Object.keys(cur).length) byEntity.set(uri, r);
  }
}

const segmentId = $('Build SPARQL Query').first().json.segment_id;
const output = [];

for (const [uri, r] of byEntity) {
  const name = r.companyLabel && r.companyLabel.value;
  // A label that is still a Q-number means the item has no English label --
  // an unusable name, and not worth a row.
  if (!name || /^Q\d+$/.test(name)) continue;

  const website = r.website && r.website.value;
  const domain = hostOf(website);
  if (!domain) continue;   // the whole point of this source

  const scoringInputs = {
    geography_signal: 'us',      // guaranteed by the P17 filter in the query
    has_reachable_presence: true // it has a published website by construction
  };

  const dissolved = r.dissolved && r.dissolved.value;
  if (dissolved) {
    scoringInputs.activity_signal = 'confirmed_dormant';
  }

  const parent = r.parentLabel && r.parentLabel.value;
  if (isMajorName(name) || (parent && isMajorName(parent))) {
    scoringInputs.major_or_oversized_signal = true;
  }

  const employees = r.employees && parseInt(r.employees.value, 10);
  if (Number.isFinite(employees) && employees > 50) {
    scoringInputs.major_or_oversized_signal = true;
  }

  output.push({
    json: {
      segment_id: segmentId,
      name: name,
      domain: domain,
      source: 'wikidata',
      source_url: uri,
      raw: {
        wikidata_uri: uri,
        website: website,
        inception: r.inception ? r.inception.value : null,
        dissolved: dissolved || null,
        parent_organisation: parent || null,
        employees: Number.isFinite(employees) ? employees : null,
        scoring_inputs: scoringInputs
      }
    }
  });
}

return output;

// Node: Summarize For Source Run  |  Mode: Run Once for All Items
// This node is a PARALLEL branch off "Filter, Score, and Shape for
// Staging" - it reads the same admitted-candidate items that also flow
// to the staging_candidates insert, and collapses them into one summary
// row for source_runs. It does not run after that insert; it runs
// alongside it, on the same input.

// SHARED BY EVERY CONNECTOR (2026-08-24). `source` is read off the incoming
// items rather than hardcoded, so the same node serves YouTube, News RSS,
// X-intent, Wikidata and AICP without five near-identical copies drifting
// apart. Each connector's shaping node already stamps `source` on every row.
const items = $input.all();
const first = items.length > 0 ? items[0].json : {};
const segmentId = first.segment_id || null;
const source = first.source || 'unknown';

return [{
  json: {
    segment_id: segmentId,
    source: source,
    candidates_found: items.length,
    candidates_new: items.length, // dedupe against EXISTING entities happens later, at the promote step (P9)
    status: 'succeeded'
  }
}];
